    bg_val = 9

    # Find all foreground positions
    fg_positions = [(i,j) for i in range(len(test_grid)) for j in range(len(test_grid[0])) 
                   if test_grid[i][j] == fg_val]

    print(f"Foreground pixels (8s): {len(fg_positions)}")

    # Group by connected component (using simple flood fill / BFS)
    visited = set()
    components = []

    def get_neighbors(r, c):
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < len(test_grid) and 0 <= nc < len(test_grid[0]):
                if test_grid[nr][nc] == fg_val and (nr, nc) not in visited:
                    yield nr, nc

    for start_r, start_c in fg_positions:
        if (start_r, start_c) in visited:
            continue

        comp = []
        stack = [(start_r, start_c)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            comp.append((r, c))

            for nr, nc in get_neighbors(r, c):
                stack.append((nr, nc))

        components.append(comp)

    print(f"Number of connected components: {len(components)}")

    for i, comp in enumerate(components[:5]):  # Show first 5
